79	async function main() {
80	  const templateIdByFamily = new Map<string, string>();
81	  let sort = 40;
82	  for (const t of TEMPLATES) {
83	    const os = await db.osTemplate.upsert({
84	      where: { slug: t.family },
85	      create: {
86	        slug: t.family, name: t.name, category: "APPLICATION", family: t.family, version: "", logo: t.family,
87	        vmid: 9000, baseVmid: 9000, setupScript: t.setupScript, minRamMB: t.minRamMB, minDiskGB: t.minDiskGB,
88	        licenseRequired: false, featured: false, sortOrder: sort++, active: true,
89	      },
90	      update: { name: t.name, setupScript: t.setupScript, minRamMB: t.minRamMB, minDiskGB: t.minDiskGB, active: true },
91	    });
92	    templateIdByFamily.set(t.family, os.id);
93	    console.log(`  osTemplate ${t.family.padEnd(16)} → ${os.id}`);
94	  }
95	
96	  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { ramMB: "asc" } });
97	  if (plans.length === 0) throw new Error("No active VPS plans — run the main seed first.");
98	  const largest = plans[plans.length - 1];
99	
100	  let created = 0, updated = 0;
101	  const sortByGame = new Map<string, number>();
102	  for (const spec of TIERS) {
103	    const basePlan = plans.find((p) => p.ramMB >= spec.ramMB) ?? largest;
104	    const osId = templateIdByFamily.get(spec.gameFamily) ?? null;
105	    const sortOrder = sortByGame.get(spec.gameFamily) ?? 0;
106	    sortByGame.set(spec.gameFamily, sortOrder + 1);
107	    const data = {
108	      gameFamily: spec.gameFamily, name: spec.name, ramMB: spec.ramMB, cpuCores: spec.cpuCores, diskGB: spec.diskGB,
109	      slots: spec.slots, priceCents: spec.priceCents, termMonths: 1, basePlanId: basePlan.id, osTemplateId: osId,
110	      featured: spec.featured ?? false, active: true, sortOrder,
111	    };
112	    const existing = await db.gamePlan.findFirst({ where: { gameFamily: spec.gameFamily, name: spec.name } });
113	    if (existing) { await db.gamePlan.update({ where: { id: existing.id }, data }); updated++; }
114	    else { await db.gamePlan.create({ data }); created++; }
115	    console.log(`  plan ${spec.name.padEnd(38)} base=${basePlan.name}`);
116	  }
117	  console.log(`\nWave 2: ${TEMPLATES.length} OsTemplates, GamePlans ${created} created / ${updated} updated.`);
118	}
119	
120	main().catch((e) => { console.error(e); process.exit(1); }).finally(() => db.$disconnect());
