1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import type { SftpServer } from "../lib/sftp";
4	import { withServerSsh, exec, SETUP_TIMEOUT_MS } from "../lib/ssh-exec";
5	import {
6	  controlSpec,
7	  isGameFamily,
8	  isPowerAction,
9	  remoteLocateDir,
10	  runRcon,
11	  parsePlayers,
12	  computeNextRun,
13	  computeNextIntervalRun,
14	  shq,
15	  isSafeRemotePath,
16	  GAME_BACKUP_DIR,
17	  type GameControlSpec,
18	} from "../lib/game-control";
19	import type { Job } from "@prisma/client";
20	
21	/**
22	 * Game server control-panel worker handlers.
23	 *
24	 * Registered in worker/index.ts:
25	 *   GAME_POWER:  gamePower,
26	 *   GAME_BACKUP: gameBackup,
27	 * and `gameScheduleSweep()` called on a ~60s timer.
28	 *
29	 * Everything runs over the platform's existing SSH (lib/ssh-exec withServerSsh —
30	 * host/port/root-password derived exactly like lib/sftp). Family/unit/path values
31	 * that reach the shell are compile-time constants or allowlisted (lib/game-control),
32	 * and the root password is never surfaced in an error (only a trimmed remote stderr
33	 * is, which never contains it).
34	 *
35	 * SANDBOX / no VM: handlers notify a simulation and touch nothing.
36	 */
37	
38	const CONTROL_FIELDS = {
39	  id: true,
40	  userId: true,
41	  hostname: true,
42	  status: true,
43	  rootPassword: true,
44	  rootPasswordEnc: true,
45	  sshPort: true,
46	  dedicatedIp: { select: { address: true } },
47	  osTemplate: { select: { family: true } },
48	  gamePlan: { select: { gameFamily: true } },
49	} as const;
50	
51	type ControlServer = {
52	  id: string;
53	  userId: string;
54	  hostname: string;
55	  status: string;
56	  rootPassword: string | null;
57	  rootPasswordEnc: string | null;
58	  sshPort: number | null;
59	  dedicatedIp: { address: string } | null;
60	  osTemplate: { family: string | null };
61	  gamePlan: { gameFamily: string | null } | null;
62	};
63	
64	async function notify(userId: string, title: string, body?: string, href?: string) {
65	  try {
66	    await db.notification.create({ data: { userId, title, body, href } });
67	  } catch (e) {
68	    console.error("[game-control] notify failed", e);
69	  }
70	}
71	
72	function resolveSpec(server: ControlServer): GameControlSpec {
73	  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
74	  if (!isGameFamily(fam)) throw new Error("not a game server");
75	  const spec = controlSpec(fam);
76	  if (!spec) throw new Error("no control spec for family");
77	  return spec;
78	}
79	
80	/**
81	 * Build the remote unit-resolution + systemctl script. `hints`/`family` come from
82	 * the family's control spec (compile-time constants); `action` is one of the three
83	 * allowlisted verbs. Emits NXGP markers so a clean SSH exit is never mistaken for
84	 * a successful action (the same discipline as worker/game-update.ts).
85	 */
86	function powerScript(spec: GameControlSpec, action: string): string {
87	  const hints = spec.serviceHints.map(shq).join(" ");
88	  return [
89	    `unit=""`,
90	    `for c in ${hints}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
91	    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(spec.family)} | head -1 | awk '{print $1}'); fi`,
92	    `if [ -z "$unit" ]; then echo "NXGP:UNIT:NONE"; exit 0; fi`,
93	    `echo "NXGP:UNIT:$unit"`,
94	    `systemctl ${action} "$unit" >/dev/null 2>&1; echo "NXGP:RC:$?"`,
95	    `st=$(systemctl is-active "$unit" 2>/dev/null); echo "NXGP:STATE:${"$"}{st:-unknown}"`,
96	    `echo "NXGP:END"`,
97	  ].join("\n");
98	}
99	
100	/** GAME_POWER — start/stop/restart the game SERVICE (not the VM). */
101	export async function gamePower(job: Job): Promise<void> {
102	  if (!job.serverId) throw new Error("game power: missing serverId");
103	  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
104	  if (!server) throw new Error(`Server ${job.serverId} not found`);
105	  const spec = resolveSpec(server);
106	
107	  const p = (job.payload ?? {}) as { action?: string; announce?: boolean };
108	  const action = String(p.action ?? "");
109	  if (!isPowerAction(action)) throw new Error(`unsupported power action: ${action}`);
110	  const href = `/dashboard/servers/${server.id}?tab=manage`;
111	
112	  if (SANDBOX) {
113	    await notify(
114	      server.userId,
115	      `Game service ${action} (sandbox) on ${server.hostname}`,
116	      `Sandbox only — no VM was contacted; the ${spec.label} service was not ${action}ed.`,
117	      href
118	    );
119	    return;
120	  }
121	  if (server.status !== "RUNNING") throw new Error("game power: VM is not running");
122	
123	  // Optional pre-restart announce over RCON (best-effort; never fails the action).
124	  if (action === "restart" && p.announce && spec.rcon === "source") {
125	    try {
126	      await withServerSsh(server as SftpServer, (conn) =>
127	        runRcon(conn, spec, "say Server is restarting now (scheduled/maintenance).")
128	      );
129	    } catch (e) {
130	      console.error("[game-control] restart announce failed (continuing)", e);
131	    }
132	  }
133	
134	  const out = await withServerSsh(server as SftpServer, (conn) => exec(conn, powerScript(spec, action), SETUP_TIMEOUT_MS));
135	  const text = out.stdout;
136	  if (/NXGP:UNIT:NONE/.test(text)) {
137	    await notify(server.userId, `Could not ${action} the ${spec.label} service`, `No game service unit was found on ${server.hostname}.`, href);
138	    throw new Error("game power: no service unit found");
139	  }
140	  const rc = Number(/NXGP:RC:(-?\d+)/.exec(text)?.[1] ?? "1");
141	  const state = /NXGP:STATE:(\w+)/.exec(text)?.[1] ?? "unknown";
142	  if (!/NXGP:END/.test(text) || rc !== 0) {
143	    await notify(server.userId, `Could not ${action} the ${spec.label} service`, `The ${action} did not complete on ${server.hostname} (state: ${state}).`, href);
144	    throw new Error(`game power: ${action} failed rc=${rc} state=${state}`);
145	  }
146	  await notify(
147	    server.userId,
148	    `${spec.label} service ${action}ed on ${server.hostname}`,
149	    action === "stop" ? "The game service was stopped." : `The game service was ${action}ed (now ${state}).`,
150	    href
151	  );
152	}
153	
154	/** GAME_BACKUP — archive the world/save dir into a downloadable .tar.gz. */
155	export async function gameBackup(job: Job): Promise<void> {
156	  if (!job.serverId) throw new Error("game backup: missing serverId");
157	  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
158	  if (!server) throw new Error(`Server ${job.serverId} not found`);
159	  const spec = resolveSpec(server);
160	  const href = `/dashboard/servers/${server.id}?tab=manage`;
161	
162	  if (SANDBOX) {
163	    await notify(server.userId, `World backup created (sandbox) on ${server.hostname}`, `Sandbox only — no VM was contacted for the ${spec.label} world backup.`, href);
164	    return;
165	  }
166	  if (server.status !== "RUNNING") throw new Error("game backup: VM is not running");
167	
168	  const outcome = await withServerSsh(server as SftpServer, async (conn) => {
169	    const dir = await remoteLocateDir(conn, spec.dataRoots);
170	    if (!dir || !isSafeRemotePath(dir)) return { ok: false, msg: "Could not locate the world/save directory." };
171	    // Timestamped archive under the fixed backup dir. `parent`/`base` are derived
172	    // from the located (allowlisted) dir; every value interpolated is single-quoted.
173	    const ts = new Date().toISOString().replace(/[-:]/g, "").replace(/\..+$/, "").replace("T", "-");
174	    const archive = `${GAME_BACKUP_DIR}/${spec.family}-${ts}.tar.gz`;
175	    const parent = dir.replace(/\/[^/]+$/, "") || "/";
176	    const base = dir.replace(/^.*\//, "");
177	    const script =
178	      `mkdir -p ${shq(GAME_BACKUP_DIR)} && ` +
179	      `tar czf ${shq(archive)} -C ${shq(parent)} ${shq(base)} 2>&1 && ` +
180	      `stat -c '%s' ${shq(archive)}`;
181	    const r = await exec(conn, script, SETUP_TIMEOUT_MS);
182	    if (r.code !== 0) return { ok: false, msg: (r.stderr || r.stdout).trim().slice(0, 200) || "tar failed" };
183	    const size = Number(r.stdout.trim().split(/\r?\n/).pop());
184	    return { ok: true, archive, size: Number.isFinite(size) ? size : 0 };
185	  });
186	
187	  if (!outcome.ok) {
188	    await notify(server.userId, `World backup failed on ${server.hostname}`, outcome.msg, href);
189	    throw new Error(`game backup failed: ${outcome.msg}`);
190	  }
191	  const mb = ((outcome.size ?? 0) / (1024 * 1024)).toFixed(1);
192	  await notify(
193	    server.userId,
194	    `${spec.label} world backup ready on ${server.hostname}`,
195	    `Backed up your world (${mb} MB). Download it from the Manage → Worlds tab.`,
196	    href
197	  );
198	}
199	
200	/**
201	 * Fire due scheduled tasks. Selects enabled GameSchedule rows whose `nextRunAt`
202	 * has passed. For kind="restart", enqueues a GAME_POWER restart; for kind="command",
203	 * sends an RCON command directly. Advances `nextRunAt` appropriately (daily or
204	 * interval-based). Idempotent / safe on a timer.
205	 */
206	export async function gameScheduleSweep(): Promise<void> {
207	  const now = new Date();
208	  const due = await db.gameSchedule.findMany({
209	    where: { enabled: true, nextRunAt: { lte: now } },
210	    include: { server: { select: { id: true, status: true, osTemplate: { select: { family: true } }, gamePlan: { select: { gameFamily: true } } } } },
211	    take: 100,
212	  });
213	  if (due.length === 0) return;
214	
215	  for (const s of due) {
216	    // Always advance the clock first so a server that is down / mid-operation does
217	    // not cause the same row to be reselected every tick.
218	    const nextRunAt = s.intervalMinutes
219	      ? computeNextIntervalRun(s.intervalMinutes, now)
220	      : computeNextRun(s.hour, s.minute, now);
221	    await db.gameSchedule.update({ where: { id: s.id }, data: { lastRunAt: now, nextRunAt } }).catch(() => {});
222	
223	    const fam = s.server.gamePlan?.gameFamily ?? s.server.osTemplate?.family ?? null;
224	    if (!isGameFamily(fam)) continue;
225	    if (s.server.status !== "RUNNING") continue;
226	
227	    if (s.kind === "command" && s.command) {
228	      // Send RCON command directly (e.g. save-all, weather clear).
229	      const spec = controlSpec(fam);
230	      if (!spec || spec.rcon === "none") continue;
231	      // Load full server for SSH access.
232	      const server = await db.server.findUnique({ where: { id: s.server.id }, select: CONTROL_FIELDS });
233	      if (!server) continue;
234	      try {
235	        await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, s.command!));
236	      } catch {
237	        // Best-effort: command schedules silently skip on failure.
238	      }
239	    } else {
240	      // Restart schedule: check for busy jobs first.
241	      const busy = await db.job.count({
242	        where: {
243	          serverId: s.server.id,
244	          status: { in: ["QUEUED", "RUNNING"] },
245	          type: { in: ["GAME_POWER", "GAME_BACKUP", "PROVISION", "REINSTALL", "DELETE", "RESIZE", "BACKUP_RESTORE"] as any },
246	        },
247	      });
248	      if (busy > 0) continue;
249	
250	      await db.job.create({ data: { type: "GAME_POWER", serverId: s.server.id, payload: { action: "restart", announce: s.announce } } });
251	    }
252	  }
253	}
254	
255	/**
256	 * Track player join/leave events by comparing the live RCON player list against
257	 * open PlayerSession rows (leftAt IS NULL). Runs every ~60s from the main loop.
258	 *
259	 * For each RUNNING game server with a gamePlan:
260	 *   - NEW players (in RCON but no open session) → create a PlayerSession
261	 *   - DEPARTED players (open session but not in RCON) → set leftAt = now()
262	 *   - STILL ONLINE → no-op
263	 *
264	 * Per-server try/catch so one unreachable VM never blocks the sweep.
265	 */
266	export async function playerTrackingSweep(): Promise<void> {
267	  if (SANDBOX) return;
268	
269	  const servers = await db.server.findMany({
270	    where: { status: "RUNNING", gamePlanId: { not: null } },
271	    select: CONTROL_FIELDS,
272	  });
273	
274	  const now = new Date();
